PRAGMA foreign_keys=ON;
CREATE TABLE albums(id TEXT PRIMARY KEY,name TEXT,sort_name TEXT,year INTEGER,genre TEXT,cover_r2_key TEXT,song_count INTEGER,duration INTEGER,size INTEGER,compilation INTEGER,created_at INTEGER,updated_at INTEGER);
CREATE TABLE song_masters(id TEXT PRIMARY KEY,album_id TEXT,title TEXT,disc INTEGER,track INTEGER,duration INTEGER,updated_at INTEGER);
CREATE TABLE song_instances(id TEXT PRIMARY KEY,master_id TEXT,storage_object_id TEXT,source_id TEXT,source_type TEXT,suffix TEXT,size INTEGER,missing INTEGER,tag_scanned INTEGER);
CREATE TABLE storage_objects(id TEXT PRIMARY KEY,physical_key TEXT,size INTEGER);
CREATE TABLE storage_entries(id TEXT PRIMARY KEY,instance_id TEXT,object_id TEXT,parent_id TEXT,path TEXT,kind TEXT);
CREATE TABLE album_display_groups(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,sort_name TEXT,created_at INTEGER,updated_at INTEGER);
CREATE TABLE album_display_group_members(group_id TEXT NOT NULL,album_id TEXT NOT NULL UNIQUE,sort_order INTEGER NOT NULL,PRIMARY KEY(group_id,album_id),FOREIGN KEY(group_id) REFERENCES album_display_groups(id),FOREIGN KEY(album_id) REFERENCES albums(id));
CREATE TABLE work_queue(id TEXT PRIMARY KEY,status TEXT CHECK(status IN ('queued','processing')));
